										boxShadow: "2px 2px 0 color-mix(in srgb, var(--red) 45%, transparent)",
									})
									: css({
										borderColor: "var(--accent-green)",
										color: "var(--accent-green)",
										background: "color-mix(in srgb, var(--accent-green) 10%, transparent)",
										boxShadow: "2px 2px 0 color-mix(in srgb, var(--accent-green) 45%, transparent)",
										_hover: { background: "color-mix(in srgb, var(--accent-green) 18%, transparent)" },
									}),
							)}
						>
							<Power size={18} />
							{active ? "END SESSION" : "START SESSION"…12582 tokens truncated…,
  onClose,
  onSubmit,
}: {
  open: boolean;
  type: "up" | "down";
  onClose: () => void;
  onSubmit: (type: "up" | "down", comment: string) => void;
}) {
  const [comment, setComment] = useState("");

  useEffect(() => {
    if (open) setComment("");
  }, [open]);

  if (!open) return null;

  return (
    <div
      className={css({
