        justifyContent: "center",
        backgroundColor: "rgb(0 0 0 / 0.5)",
        paddingInline: "1rem",
        backdropFilter: "blur(4px)",
      })}
      onClick={onClose}
    >
      <div
        className={css({
          width: "100%",
          maxWidth: "28rem",
          borderRadius: "0.5rem",
